final class LootDisplayItem
{
    private final int itemId;
    private final int quantity;
    private final long unitPrice;
    private final String dropRate;
    private final double dropRateOneIn;
    private final boolean pricePending;

    LootDisplayItem(int itemId, int quantity, long unitPrice)
    {
        this(itemId, quantity, unitPrice, null, 0.0);
    }

    LootDisplayItem(int itemId, int quantity, long unitPrice, String dropRate)
    {
        this(itemId, quantity, unitPrice, dropRate, 0.0);
    }

    LootDisplayItem(int itemId, int quantity, long unitPrice, String dropRate, double dropRateOneIn)
    {
        this(itemId, quantity, unitPrice, dropRate, dropRateOneIn, false);
    }

    LootDisplayItem(int itemId, int quantity, long unitPrice, String dropRate, double dropRateOneIn, boolean pending)
    {
        this.itemId = itemId;
        this.quantity = quantity;
        this.unitPrice = pending ? 0 : unitPrice;
        this.dropRate = dropRate;
        this.dropRateOneIn = dropRateOneIn;
        this.pricePending = pending;
    }

    boolean isPricePending() { return pricePending; }

    int getItemId()
    {
        return itemId;
    }

    int getQuantity()
    {
        return quantity;
    }

    long getUnitPrice()
    {
        return unitPrice;
    }

    long getTotalValue()
    {
        return unitPrice * quantity;
    }

    String getDropRate()
    {
        return dropRate;
    }

    double getDropRateOneIn()
    {
        return dropRateOneIn;
    }

    static List<LootDisplayItem> mergeDuplicates(List<LootDisplayItem> items)
    {
        Map<Integer, LootDisplayItem> merged = new LinkedHashMap<>();
        for (LootDisplayItem item : items)
        {
            LootDisplayItem existing = merged.get(item.itemId);
            if (existing == null)
            {
                merged.put(item.itemId, item);
                continue;
            }

            long combinedQuantity = (long) existing.quantity + item.quantity;
            int quantity = (int) Math.min(Integer.MAX_VALUE, combinedQuantity);
            String dropRate = existing.dropRate != null ? existing.dropRate : item.dropRate;
            double oneIn = existing.dropRateOneIn > 0.0 ? existing.dropRateOneIn : item.dropRateOneIn;
            merged.put(item.itemId, new LootDisplayItem(item.itemId, quantity, existing.unitPrice, dropRate, oneIn,
                existing.pricePending || item.pricePending));
        }
        return new ArrayList<>(merged.values());
    }
}

package com.lootpop;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

/** One set of slots for settled items, reveal destinations, quantities, overflow and hit testing. */
final class LootGridLayout
{
    static List<Rectangle> slots(int[] widths, int x, int y, int availableWidth, int columns)
    {
        List<Rectangle> result = new ArrayList<>();
        for (int start = 0; start < widths.length; start += columns)
        {
            int end = Math.min(widths.length, start + columns);
            int occupied = 0;
            for (int i = start; i < end; i++) { occupied += widths[i]; }
            int gaps = end - start - 1;
            int gap = gaps == 0 ? 0 : Math.max(1, Math.min(8, (availableWidth - occupied) / gaps));
            int rowWidth = occupied + gap * gaps;
            int cursor = x + (availableWidth - rowWidth) / 2;
            for (int i = start; i < end; i++)
            {
                result.add(new Rectangle(cursor, y + (start / columns) * 34, widths[i], 32));
                cursor += widths[i] + gap;
            }
        }
        return result;
    }
}

