package com.lootpop;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Insights use observed snapshots only. Never mix price modes or infer kills/profit. */
final class LootInsights
{
    static Summary source(List<LootHistoryEntry> entries, String source, PriceMode mode)
    {
        Summary result = new Summary(mode);
        Set<String> ids = new LinkedHashSet<>();
        entries.stream().filter(e -> e.getPriceMode() == mode && source.equals(e.getSourceName()))
            .sorted(Comparator.comparingLong(LootHistoryEntry::getTimestamp))
            .filter(e -> ids.add(e.getId())).forEach(result::record);
        return result;
    }

    static final class Highlight
    {
        final LootHistoryItem item;
        final String source;
        final long timestamp;

        Highlight(LootHistoryItem item, LootHistoryEntry entry)
        { this.item = item; source = entry.getSourceName(); timestamp = entry.getTimestamp(); }
    }

    static final class Summary
    {
        final PriceMode mode;
        int drops, pendingDrops;
        long total, firstAt, lastAt;
        LootHistoryEntry bestDrop;
        Highlight valuable, rarest;
        final List<Highlight> unlocks = new ArrayList<>();
        private final Set<String> unlockKeys = new LinkedHashSet<>();

        Summary(PriceMode mode) { this.mode = mode; }

        Summary(Summary original)
        {
            mode = original.mode; drops = original.drops; pendingDrops = original.pendingDrops;
            total = original.total; firstAt = original.firstAt; lastAt = original.lastAt;
            bestDrop = original.bestDrop; valuable = original.valuable; rarest = original.rarest;
            unlocks.addAll(original.unlocks); unlockKeys.addAll(original.unlockKeys);
        }

        void record(LootHistoryEntry entry)
        {
            if (entry.getPriceMode() != mode) { throw new IllegalArgumentException("Mixed price modes"); }
            firstAt = drops == 0 ? entry.getTimestamp() : Math.min(firstAt, entry.getTimestamp());
            lastAt = Math.max(lastAt, entry.getTimestamp());
            drops++; total += entry.getTotalValue();
            if (entry.hasPendingPrices()) { pendingDrops++; }
            else if (bestDrop == null || entry.getTotalValue() > bestDrop.getTotalValue()) { bestDrop = entry; }
            for (LootHistoryItem item : entry.getItems())
            {
                Highlight observed = new Highlight(item, entry);
                if (!item.isPricePending() && (valuable == null || item.getStackValue() > valuable.item.getStackValue()))
                { valuable = observed; }
                double chance = chance(item);
                if (Double.isFinite(chance) && chance > 0 && (rarest == null || chance > chance(rarest.item)))
                { rarest = observed; }
            }
            confirmCollection(entry);
        }

        void confirmCollection(LootHistoryEntry entry)
        {
            for (LootHistoryItem item : entry.getItems())
            {
                String key = item.getItemId() >= 0 ? "id:" + item.getItemId() : "name:" + item.getName();
                if (item.isCollectionLogItem() && unlockKeys.add(key))
                {
                    unlocks.add(0, new Highlight(item, entry));
                    unlocks.sort(Comparator.comparingLong((Highlight h) -> h.timestamp).reversed());
                    while (unlocks.size() > 6) { unlocks.remove(unlocks.size() - 1); }
                }
            }
        }

        int logSlots() { return unlockKeys.size(); }

        private static double chance(LootHistoryItem item)
        {
            String rate = item.getDropRate();
            // Multiple possible rates have no single meaningful ranking.
            return rate == null || rate.contains("|") || rate.contains("+ more")
                || rate.contains(";") || rate.contains(" or ") ? 0
                : DropRateService.parseOneIn(rate.replace(",", ""));
        }
    }

    private LootInsights() { }
}

package com.lootpop;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Saved observations, not a kill counter or an estimate of unobserved loot. */
final class LootJournal
{
    final List<LootHistoryEntry> entries = new ArrayList<>();
    final Map<String, Long> bests = new LinkedHashMap<>();
    final List<LootHistoryEntry> trophies = new ArrayList<>();

    synchronized long record(LootHistoryEntry entry, int limit, int days, long now)
    {
        return record(entry, limit, days, now, 500);
    }

    synchronized long record(LootHistoryEntry entry, int limit, int days, long now, int trophyLimit)
    {
        if (entries.stream().anyMatch(e -> e.getId().equals(entry.getId()))
            || trophies.stream().anyMatch(e -> e.getId().equals(entry.getId()))) { return 0; }
        String key = entry.sourceKey();
        long previous = bests.getOrDefault(key, 0L);
        if (!entry.hasPendingPrices() && entry.getTotalValue() > previous)
        {
            for (LootHistoryEntry old : trophies)
            {
                if (old.sourceKey().equals(key)) { old.setSourceBest(false); }
            }
            for (LootHistoryEntry old : entries)
            {
                if (old.sourceKey().equals(key)) { old.setSourceBest(false); }
            }
            entry.setSourceBest(true);
            bests.put(key, entry.getTotalValue());
            if (previous > 0) { entry.setPreviousBest(previous); }
        }
        entries.add(0, entry);
        keepTrophy(entry, trophyLimit);
        prune(limit, days, now);
        return entry.getPreviousBest();
    }

    synchronized void prune(int limit, int days, long now)
    {
        long cutoff = now - Math.max(1, days) * 86_400_000L;
        entries.removeIf(e -> e.getTimestamp() < cutoff);
        while (entries.size() > Math.max(1, limit)) { entries.remove(entries.size() - 1); }
        // Bound source metadata too; observed sources normally number far fewer than this.
        while (bests.size() > 4096) { bests.remove(bests.keySet().iterator().next()); }
    }

    synchronized List<LootHistoryEntry> snapshot() { return new ArrayList<>(entries); }
    synchronized List<LootHistoryEntry> trophySnapshot() { return new ArrayList<>(trophies); }

    synchronized void keepTrophy(LootHistoryEntry entry, int limit)
    {
        trophies.removeIf(e -> !e.isTrophy());
        if (entry.isTrophy() && trophies.stream().noneMatch(e -> e.getId().equals(entry.getId())))
        { trophies.add(entry); }
        trimTrophies(limit);
    }

    synchronized void trimTrophies(int limit)
    {
        trophies.sort(java.util.Comparator.comparingLong(LootHistoryEntry::getTimestamp).reversed());
        while (trophies.size() > Math.max(1, limit)) { trophies.remove(trophies.size() - 1); }
    }
}

package com.lootpop;

import java.io.IOException;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.IntSupplier;

/** One ordered IO lane: profile switches, observations and writes can never overtake one another. */
final class LootJournalService implements AutoCloseable
{
    private final LootJournalStore store;
    private final Runnable changed;
    private final IntSupplier limit;
    private final IntSupplier days;
    private final IntSupplier trophyLimit;
    private final ScheduledExecutorService scheduler;
    private final Executor io;
    private CompletableFuture<Void> tail = CompletableFuture.completedFuture(null);
    private volatile State current;
    private volatile boolean closed;

    LootJournalService(LootJournalStore store, Runnable changed, IntSupplier limit, IntSupplier days,
        ScheduledExecutorService scheduler)
    {
        this(store, changed, limit, days, scheduler, () -> 500);
    }

    LootJournalService(LootJournalStore store, Runnable changed, IntSupplier limit, IntSupplier days,
        ScheduledExecutorService scheduler, IntSupplier trophyLimit)
    {
        this.store = store; this.changed = changed; this.limit = limit; this.days = days;
        this.scheduler = scheduler;
        this.trophyLimit = trophyLimit;
        this.io = task ->
        {
            synchronized (LootJournalService.this)
            {
                tail = tail.handle((value, failure) -> null).thenRunAsync(task, scheduler);
            }
        };
    }

    synchronized void switchProfile(String profile)
    {
        if (closed) { return; }
        State previous = current;
        if (previous != null && previous.profile.equals(profile)) { return; }
        State next = profile == null || profile.isEmpty() ? null : new State(profile);
        current = next;
        io.execute(() ->
        {
            if (previous != null) { flush(previous); }
            if (next != null)
            {
                try
                {
                    next.journal = store.load(next.profile);
                    int before = next.journal.snapshot().size();
                    next.journal.prune(limit.getAsInt(), days.getAsInt(), System.currentTimeMillis());
                    int trophyCount = next.journal.trophySnapshot().size();
                    next.journal.trimTrophies(trophyLimit.getAsInt());
                    if (trophyCount != next.journal.trophySnapshot().size()) { dirty(next); }
                    if (next.journal.snapshot().size() != before) { dirty(next); }
                }
                catch (IOException failure)
                {
                    next.readOnly = true;
                    next.error = "Saved file could not be read. It was left untouched.";
                }
                next.loading = false;
            }
            changed.run();
        });
    }

    synchronized void record(LootHistoryEntry entry, LootNotification popup, boolean celebrate, long minimum)
    {
        State state = current;
        if (closed || state == null) { return; }
        io.execute(() ->
        {
            if (state.readOnly) { return; }
            long previous = state.journal.record(entry, limit.getAsInt(), days.getAsInt(), System.currentTimeMillis(), trophyLimit.getAsInt());
            if (celebrate && previous > 0 && entry.getTotalValue() >= minimum)
            {
                popup.markPersonalBest(previous);
            }
            dirty(state);
            changed.run();
        });
    }

    synchronized void confirmCollection(String source, long time)
    {
        confirmCollection(source, time, -1);
    }

    synchronized void confirmCollection(String source, long time, int itemId)
    {
        State state = current;
        if (closed || state == null) { return; }
        io.execute(() ->
        {
            if (state.readOnly) { return; }
            java.util.Map<String, LootHistoryEntry> candidates = new java.util.LinkedHashMap<>();
            for (LootHistoryEntry entry : state.journal.snapshot()) { candidates.put(entry.getId(), entry); }
            for (LootHistoryEntry entry : state.journal.trophySnapshot()) { candidates.put(entry.getId(), entry); }
            for (LootHistoryEntry entry : candidates.values())
            {
                if (entry.getTimestamp() == time && entry.getSourceName().equals(source))
                {
                    entry.setCollectionLogUnlock(true);
                    for (LootHistoryItem item : entry.getItems())
                    { if (item.getItemId() == itemId) { item.setCollectionLogItem(true); } }
                    state.journal.keepTrophy(entry, trophyLimit.getAsInt());
                    dirty(state);
                    changed.run();
                    break;
                }
            }
        });
    }

    synchronized void clear()
    {
        State state = current;
        if (closed || state == null) { return; }
        io.execute(() ->
        {
            if (state.readOnly) { return; }
            state.journal = new LootJournal();
            state.dirty = true;
            flush(state);
            changed.run();
        });
    }

    List<LootHistoryEntry> entries()
    {
        State state = current;
        return state == null ? Collections.emptyList() : state.journal.snapshot();
    }

    String status()
    {
        State state = current;
        if (state == null) { return "Log in to open this character's journal"; }
        if (state.loading) { return "Opening local journal..."; }
        return state.error == null ? "Stored on this device / this character only" : state.error;
    }

    String notice()
    {
        State state = current;
        if (state == null) { return "Log in to open this character's journal"; }
        if (state.loading) { return "Opening local journal..."; }
        return state.error == null ? "" : state.error;
    }

    List<LootHistoryEntry> trophies()
    {
        State state = current;
        return state == null ? Collections.emptyList() : state.journal.trophySnapshot();
    }

    boolean canClear() { State state = current; return state != null && !state.loading && !state.readOnly; }

    private void dirty(State state)
    {
        state.dirty = true;
        if (state.save != null) { state.save.cancel(false); }
        if (closed) { flush(state); }
        else { state.save = scheduler.schedule(() -> io.execute(() -> { flush(state); changed.run(); }), 700, TimeUnit.MILLISECONDS); }
    }

    private void flush(State state)
    {
        if (state.save != null) { state.save.cancel(false); state.save = null; }
        if (!state.dirty || state.readOnly) { return; }
        try { store.save(state.profile, state.journal); state.dirty = false; state.error = null; }
        catch (IOException failure) { state.error = "Journal save failed. Check local folder permissions."; }
    }

    @Override
    public synchronized void close()
    {
        if (closed) { return; }
        closed = true;
        State state = current;
        io.execute(() -> { if (state != null) { flush(state); } });
    }

    private static final class State
    {
        final String profile;
        volatile LootJournal journal = new LootJournal();
        volatile boolean loading = true;
        volatile boolean readOnly;
        volatile String error;
        boolean dirty;
        ScheduledFuture<?> save;
        State(String profile) { this.profile = profile; }
    }
}

package com.lootpop;

import com.google.gson.Gson;
import com.google.gson.FieldNamingPolicy;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;
import net.runelite.client.util.Filepath;

/** Only item metadata is stored. No sprites, login names, credentials or network requests. */
final class LootJournalStore
{
    @FunctionalInterface
    interface Directory
    {
        Filepath get() throws IOException;
    }

    private final Directory directoryProvider;
    private Filepath directory;
    private final Gson gson;

    LootJournalStore(Directory directoryProvider, Gson clientGson)
    {
        this.directoryProvider = directoryProvider;
        // Keep the on-disk field names stable while inheriting RuneLite's Gson configuration.
        this.gson = clientGson.newBuilder().setFieldNamingPolicy(FieldNamingPolicy.IDENTITY).create();
    }

    // Resolved on the journal's ordered IO lane, not on the client thread. Failed migration
    // propagates to the service's read-only handling rather than creating an empty journal.
    private Filepath directory() throws IOException
    {
        if (directory == null) { directory = directoryProvider.get(); }
        return directory;
    }

    Filepath fileFor(String profile) throws IOException
    {
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(profile.getBytes(StandardCharsets.UTF_8));
            StringBuilder name = new StringBuilder();
            for (byte b : digest) { name.append(String.format(java.util.Locale.ROOT, "%02x", b & 255)); }
            return directory().joinSegment(name + ".json");
        }
        catch (NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }

    LootJournal load(String profile) throws IOException
    {
        Filepath file = fileFor(profile);
        if (!file.exists()) { return new LootJournal(); }
        if (file.size() > 16 * 1024 * 1024) { throw new IOException("Journal exceeds the safe read limit"); }
        try (Reader reader = file.openBufferedReader())
        {
            Data data = gson.fromJson(reader, Data.class);
            if (data == null || (data.version != 1 && data.version != 2) || data.entries == null || data.bests == null
                || data.entries.size() > 7000 || data.bests.size() > 4096)
            { throw new IOException("Unsupported journal format"); }
            LootJournal journal = new LootJournal();
            Map<String, LootHistoryEntry> all = new LinkedHashMap<>();
            for (Entry saved : data.entries)
            {
                if (saved == null || saved.source == null || saved.source.length() > 300 || saved.value < 0
                    || saved.time <= 0 || saved.items == null || saved.items.size() > 128
                    || (data.version == 2 && (saved.id == null || saved.id.length() > 64 || saved.id.isEmpty())))
                { throw new IOException("Invalid journal entry"); }
                List<LootHistoryItem> items = new ArrayList<>();
                for (Item item : saved.items)
                {
                    if (item == null || item.id < 0 || item.qty <= 0 || item.name == null || item.name.length() > 300
                        || item.ge < 0 || item.ha < 0 || item.value < 0 || (item.chance != null && item.chance.length() > 100))
                    { throw new IOException("Invalid journal item"); }
                    items.add(new LootHistoryItem(item.qty, item.name, item.ge, item.ha, item.value,
                        item.chance, item.rarity == null ? DropRarity.UNKNOWN : item.rarity, null).withItemId(item.id)
                        .withPriceState(item.pending, item.gePending));
                    items.get(items.size() - 1).setCollectionLogItem(item.collection);
                }
                LootHistoryEntry entry = new LootHistoryEntry(saved.source, saved.value, saved.time,
                    saved.rarity == null ? DropRarity.UNKNOWN : saved.rarity, items);
                entry.setCollectionLogUnlock(saved.collection);
                entry.setPreviousBest(Math.max(0, saved.previous));
                entry.setPriceMode(saved.mode == null ? PriceMode.GRAND_EXCHANGE : saved.mode);
                if (data.version == 2) { entry.setId(saved.id); }
                entry.setSourceBest(saved.sourceBest);
                if (all.put(entry.getId(), entry) != null) { throw new IOException("Duplicate journal entry"); }
            }
            for (Map.Entry<String, Long> best : data.bests.entrySet())
            {
                if (best.getKey() == null || best.getKey().length() > 400 || best.getValue() == null || best.getValue() < 0)
                { throw new IOException("Invalid journal record"); }
                journal.bests.put(best.getKey(), best.getValue());
            }
            if (data.version == 1)
            {
                if (all.size() > 5000) { throw new IOException("Too many legacy entries"); }
                journal.entries.addAll(all.values());
                journal.entries.sort(java.util.Comparator.comparingLong(LootHistoryEntry::getTimestamp).reversed());
                java.util.Set<String> champions = new java.util.HashSet<>();
                for (LootHistoryEntry entry : journal.entries)
                {
                    if (entry.getTotalValue() > 0 && entry.getTotalValue() == journal.bests.getOrDefault(entry.sourceKey(), -1L)
                        && champions.add(entry.sourceKey())) { entry.setSourceBest(true); }
                    journal.keepTrophy(entry, 500);
                }
            }
            else
            {
                restoreList(data.history, all, journal.entries, 5000);
                restoreList(data.trophies, all, journal.trophies, 2000);
                for (LootHistoryEntry entry : all.values())
                {
                    if (entry.hasPendingPrices() || entry.getTotalValue() != journal.bests.getOrDefault(entry.sourceKey(), -1L))
                    { entry.setSourceBest(false); }
                }
                journal.trophies.removeIf(e -> !e.isTrophy());
            }
            journal.entries.sort(java.util.Comparator.comparingLong(LootHistoryEntry::getTimestamp).reversed());
            journal.trophies.sort(java.util.Comparator.comparingLong(LootHistoryEntry::getTimestamp).reversed());
            return journal;
        }
        catch (RuntimeException badData) { throw new IOException("Journal could not be read", badData); }
    }

    void save(String profile, LootJournal journal) throws IOException
    {
        Data data = new Data();
        data.version = 2;
        data.entries = new ArrayList<>();
        data.bests = new LinkedHashMap<>();
        data.history = new ArrayList<>();
        data.trophies = new ArrayList<>();
        synchronized (journal)
        {
            data.bests.putAll(journal.bests);
            Map<String, LootHistoryEntry> unique = new LinkedHashMap<>();
            for (LootHistoryEntry entry : journal.entries) { data.history.add(entry.getId()); unique.put(entry.getId(), entry); }
            for (LootHistoryEntry entry : journal.trophies) { data.trophies.add(entry.getId()); unique.put(entry.getId(), entry); }
            for (LootHistoryEntry entry : unique.values())
            {
                Entry saved = new Entry();
                saved.source = entry.getSourceName(); saved.value = entry.getTotalValue(); saved.time = entry.getTimestamp();
                saved.rarity = entry.getRarity(); saved.collection = entry.isCollectionLogUnlock();
                saved.previous = entry.getPreviousBest(); saved.mode = entry.getPriceMode();
                saved.id = entry.getId(); saved.sourceBest = entry.isSourceBest();
                for (LootHistoryItem item : entry.getItems())
                {
                    Item copy = new Item();
                    copy.id = item.getItemId(); copy.qty = item.getQuantity(); copy.name = item.getName();
                    copy.ge = item.getGePrice(); copy.ha = item.getHighAlchemyPrice(); copy.value = item.getStackValue();
                    copy.chance = item.getDropRate(); copy.rarity = item.getRarity(); saved.items.add(copy);
                    copy.pending = item.isPricePending(); copy.gePending = item.isGePending();
                    copy.collection = item.isCollectionLogItem();
                }
                data.entries.add(saved);
            }
        }
        Filepath root = directory();
        root.createDirectories();
        Filepath file = fileFor(profile);
        Filepath temporary = root.createTempFile("journal-", ".tmp");
        try
        {
            temporary.write(gson.toJson(data));
            if (temporary.size() > 16 * 1024 * 1024) { throw new IOException("Journal exceeds storage limit"); }
            if (file.exists())
            {
                file.copyTo(root.joinSegment(file.getFileName() + ".bak"), StandardCopyOption.REPLACE_EXISTING);
            }
            try { temporary.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
            catch (AtomicMoveNotSupportedException unsupported)
            { temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING); }
        }
        finally { temporary.deleteIfExists(); }
    }

    private static final class Data
    {
        int version;
        List<Entry> entries;
        Map<String, Long> bests;
        List<String> history;
        List<String> trophies;
    }
    private static final class Entry
    {
        String source; long value; long time; DropRarity rarity; boolean collection; long previous; PriceMode mode;
        String id; boolean sourceBest;
        List<Item> items = new ArrayList<>();
    }
    private static final class Item
    {
        int id; int qty; String name; long ge; long ha; long value; String chance; DropRarity rarity;
        boolean pending; boolean gePending; boolean collection;
    }

    private static void restoreList(List<String> ids, Map<String, LootHistoryEntry> all,
        List<LootHistoryEntry> output, int limit) throws IOException
    {
        if (ids == null || ids.size() > limit) { throw new IOException("Invalid journal index"); }
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (String id : ids)
        {
            if (!all.containsKey(id) || !seen.add(id)) { throw new IOException("Invalid journal reference"); }
            output.add(all.get(id));
        }
    }
}

package com.lootpop;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/** A quiet, readable Collection Log tag shared by the overlay and sidebar. */
final class LootLogBadge
{
    static final int WIDTH = 27, HEIGHT = 14;

    static void draw(Graphics2D graphics, int x, int y)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setColor(new Color(35, 29, 17, 245));
        g.fillRoundRect(x, y, WIDTH, HEIGHT, 4, 4);
        g.setColor(new Color(242, 197, 93));
        g.fillRoundRect(x, y + 2, 2, HEIGHT - 4, 2, 2);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
        String label = "NEW";
        int textX = x + 3 + (WIDTH - 3 - g.getFontMetrics().stringWidth(label)) / 2;
        int baseline = y + (HEIGHT - g.getFontMetrics().getHeight()) / 2 + g.getFontMetrics().getAscent();
        g.setColor(new Color(255, 225, 156));
        g.drawString(label, textX, baseline);
        g.dispose();
    }

    private LootLogBadge() {}
}

package com.lootpop;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

final class LootNotification
{
    private final String sourceName;
    private final List<LootDisplayItem> items;
    private final long totalValue;
    private long visibleAtMillis;
    private long pausedAtMillis = -1L;
    private long pausedDurationMillis;
    private volatile boolean collectionLogUnlock;
    private final long createdAtMillis;
    private final Set<Integer> collectionLogItems = ConcurrentHashMap.newKeySet();
    private volatile SealedDropSequence sealedDrop;
    private volatile boolean revealSkipped;
    private long skippedRevealDuration;
    private boolean soundPlayed;
    private boolean screenshotPending;
    private int lastRevealSoundStage = -1;
    private volatile long lateUnlockAtAge = -1L;
    private volatile long previousBest;

    void markPersonalBest(long previous) { previousBest = hasPendingPrices() ? 0 : Math.max(0, previous); }
    long getPreviousBest() { return previousBest; }
    boolean isPersonalBest() { return previousBest > 0; }
    boolean hasPendingPrices() { return items.stream().anyMatch(LootDisplayItem::isPricePending); }

    LootNotification(String sourceName, List<LootDisplayItem> items, long totalValue, long createdAtMillis)
    {
        this.sourceName = sourceName;
        this.items = Collections.unmodifiableList(new ArrayList<>(items));
        this.totalValue = totalValue;
        this.visibleAtMillis = createdAtMillis;
        this.createdAtMillis = createdAtMillis;
    }

    String getSourceName()
    {
        return sourceName;
    }

    List<LootDisplayItem> getItems()
    {
        return items;
    }

    long getCreatedAtMillis() { return createdAtMillis; }

    List<LootDisplayItem> getDisplayItems()
    {
        return sealedDrop == null ? items : sealedDrop.getItems();
    }

    SealedDropSequence getSealedDrop() { return revealSkipped ? null : sealedDrop; }
    void setSealedDrop(SealedDropSequence sequence) { sealedDrop = sequence; }
    void skipReveal(long now)
    {
        if (!revealSkipped && sealedDrop != null)
        {
            skippedRevealDuration = Math.min(getAgeMillis(now), sealedDrop.getDurationMillis());
            revealSkipped = true;
        }
    }
    long getRevealDelayMillis()
    {
        return revealSkipped ? skippedRevealDuration : sealedDrop == null ? 0 : sealedDrop.getDurationMillis();
    }
    Set<Integer> getCollectionLogItems() { return Collections.unmodifiableSet(collectionLogItems); }
    boolean isCollectionLogItem(int id) { return collectionLogItems.contains(id); }
    long getLateUnlockAtAge() { return lateUnlockAtAge; }

    boolean markCollectionLogItem(int id, long now)
    {
        if (!collectionLogItems.add(id)) { return false; }
        collectionLogUnlock = true;
        // Late messages celebrate the matching item without replaying or rearranging the drop.
        if (getAgeMillis(now) > 300 && (sealedDrop == null
            || getAgeMillis(now) >= sealedDrop.getRevealEndMillis()))
        {
            lateUnlockAtAge = getAgeMillis(now);
        }
        return true;
    }

    boolean takeSound()
    {
        if (soundPlayed) { return false; }
        soundPlayed = true;
        return true;
    }

    void requestScreenshot() { screenshotPending = true; }
    boolean takeScreenshot()
    {
        if (!screenshotPending) { return false; }
        screenshotPending = false;
        return true;
    }

    boolean takeRevealSound(int stage)
    {
        if (stage <= lastRevealSoundStage) { return false; }
        lastRevealSoundStage = stage;
        return true;
    }

    long getTotalValue()
    {
        return totalValue;
    }

    boolean isCollectionLogUnlock()
    {
        return collectionLogUnlock;
    }

    void setCollectionLogUnlock(boolean collectionLogUnlock)
    {
        this.collectionLogUnlock = collectionLogUnlock;
    }

    long getAgeMillis(long nowMillis)
    {
        long effectiveNow = pausedAtMillis >= 0L ? pausedAtMillis : nowMillis;
        return Math.max(0L, effectiveNow - visibleAtMillis - pausedDurationMillis);
    }

    void setHovered(boolean hovered, long nowMillis)
    {
        SealedDropSequence sequence = getSealedDrop();
        hovered = hovered && (sequence == null || getAgeMillis(nowMillis) >= sequence.getDurationMillis());
        if (hovered && pausedAtMillis < 0L)
        {
            pausedAtMillis = nowMillis;
        }
        else if (!hovered && pausedAtMillis >= 0L)
        {
            pausedDurationMillis += Math.max(0L, nowMillis - pausedAtMillis);
            pausedAtMillis = -1L;
        }
    }

    void restartAt(long nowMillis)
    {
        visibleAtMillis = nowMillis;
        pausedAtMillis = -1L;
        pausedDurationMillis = 0L;
        lateUnlockAtAge = -1L;
    }

    float getAlpha(long nowMillis, int displayDuration, int fadeDuration)
    {
        long age = getAgeMillis(nowMillis);
        if (age <= displayDuration)
        {
            return 1.0f;
        }

        if (fadeDuration <= 0)
        {
            return 0.0f;
        }

        float progress = (age - displayDuration) / (float) fadeDuration;
        return Math.max(0.0f, 1.0f - progress);
    }

    boolean isExpired(long nowMillis, int displayDuration, int fadeDuration)
    {
        return getAgeMillis(nowMillis) > (long) displayDuration + fadeDuration;
    }
}

package com.lootpop;

import java.awt.Component;
import java.awt.HeadlessException;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.Locale;
import javax.swing.JOptionPane;
import net.runelite.client.util.LinkBrowser;

/** Desktop side effects stay behind explicit user actions and can be tested without a browser or clipboard. */
interface LootPanelActions
{
    boolean confirmSessionReset(Component owner, int drops);
    void copyName(Component owner, String name);
    void openWiki(String name);

    static LootPanelActions desktop()
    {
        return new LootPanelActions()
        {
            @Override public boolean confirmSessionReset(Component owner, int drops)
            {
                Object[] options = {"Cancel", "Reset session"};
                return JOptionPane.showOptionDialog(owner,
                    "Reset all session sources?\n" + String.format(Locale.US, "%,d", drops)
                        + " recorded drops and the session recap will be cleared.\nSaved Journal history and trophies will not be changed.",
                    "Reset Loot Pop session", JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE,
                    null, options, options[0]) == 1;
            }

            @Override public void copyName(Component owner, String name)
            {
                try { Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(name), null); }
                catch (IllegalStateException | HeadlessException | SecurityException unavailable)
                {
                    JOptionPane.showMessageDialog(owner, "The clipboard is unavailable. Please try Copy name again.",
                        "Copy name", JOptionPane.INFORMATION_MESSAGE);
                }
            }

            @Override public void openWiki(String name) { LinkBrowser.browse(LootPopPanel.wikiSearchUrl(name)); }
        };
    }
}

