package com.lootpop;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.*;

public class PricePendingTest
{
    @Test
    public void missingTradeableGeNeverFallsBackToHighAlchemy()
    {
        LootPriceQuote quote = LootPriceQuote.of(PriceMode.GRAND_EXCHANGE, true, true, 0, 120000);
        assertTrue(quote.pending); assertTrue(quote.gePending); assertEquals(0, quote.value);
        assertTrue(quote.shouldInclude(false));
        LootPriceQuote alch = LootPriceQuote.of(PriceMode.HIGH_ALCHEMY, true, true, 0, 120000);
        assertFalse(alch.pending); assertTrue(alch.gePending); assertEquals(120000, alch.value);
    }

    @Test
    public void genuineZeroValuesAreDifferentFromUnavailableDefinitions()
    {
        LootPriceQuote zero = LootPriceQuote.of(PriceMode.GRAND_EXCHANGE, true, false, 0, 0);
        assertFalse(zero.pending); assertFalse(zero.shouldInclude(false)); assertTrue(zero.shouldInclude(true));
        assertTrue(LootPriceQuote.of(PriceMode.GRAND_EXCHANGE, false, false, 0, 0).pending);
        assertFalse(LootPriceQuote.of(PriceMode.HIGH_ALCHEMY, true, true, 0, 0).pending);
        assertTrue(LootPriceQuote.of(PriceMode.HIGH_ALCHEMY, false, false, 0, 0).pending);
        assertFalse(LootPriceQuote.of(PriceMode.GRAND_EXCHANGE, true, true, 25000, 10000).pending);
    }

    @Test
    public void pendingStacksSurviveMergingAndDoNotFailMinimumValueFilter()
    {
        LootDisplayItem pending = new LootDisplayItem(1, 1, 0, "1 / 5000", 5000, true);
        java.util.List<LootDisplayItem> merged = LootDisplayItem.mergeDuplicates(Arrays.asList(pending,
            new LootDisplayItem(1, 2, 40000)));
        assertTrue(merged.get(0).isPricePending()); assertEquals(3, merged.get(0).getQuantity());
        assertEquals(0, merged.get(0).getTotalValue());
        assertTrue(LootPriceQuote.passesMinimum(0, 1000000, merged));
        assertFalse(LootPriceQuote.passesMinimum(10, 1000000, Collections.singletonList(new LootDisplayItem(2, 1, 10))));
    }

    @Test
    public void pendingTotalsAreExplicitAndCannotTriggerPopupRecords()
    {
        assertEquals("Price pending", LootValueText.compact(0, true));
        assertEquals("100K+ gp", LootValueText.compact(100000, true));
        assertEquals("0 gp", LootValueText.compact(0, false));
        assertTrue(LootValueText.detail(100000, true).contains("incomplete"));
        LootNotification popup = new LootNotification("Boss", Collections.singletonList(
            new LootDisplayItem(1, 1, 0, null, 0, true)), 0, 1000);
        popup.markPersonalBest(50); assertFalse(popup.isPersonalBest());
    }

    @Test
    public void incompleteDropCannotCreateOrBeatJournalRecordButStillCanBeARareTrophy()
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        LootHistoryEntry pending = new LootHistoryEntry("Boss", 500000, now, DropRarity.ULTRA_RARE,
            Arrays.asList(new LootHistoryItem(1, "New item", 0, 120000, 0, "1 / 5000", DropRarity.ULTRA_RARE, null)
                .withItemId(1).withPriceState(true, true),
                new LootHistoryItem(1, "Known item", 500000, 100000, 500000, null, DropRarity.COMMON, null).withItemId(2)));
        assertEquals(0, journal.record(pending, 100, 90, now));
        assertTrue(journal.bests.isEmpty()); assertFalse(pending.isSourceBest());
        assertEquals(1, journal.trophySnapshot().size());
        assertEquals(0, journal.record(LootJournalTest.entry("Boss", 100, now + 1), 100, 90, now));
        journal.record(pending, 100, 90, now);
        assertEquals(Long.valueOf(100), journal.bests.get("GRAND_EXCHANGE:Boss"));
    }
}

package com.lootpop;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import org.junit.Test;
import static org.junit.Assert.*;

public class SealedDropPluginTest
{
    private static LootPopPlugin plugin(LootPopConfig config) throws Exception
    {
        LootPopPlugin p = new LootPopPlugin();
        Field field = LootPopPlugin.class.getDeclaredField("config");
        field.setAccessible(true);
        field.set(p, config);
        return p;
    }

    @Test
    public void fullReadingTimeIsAddedAfterRevealEvenWithoutAdaptiveTime() throws Exception
    {
        LootPopConfig config = new LootPopConfig()
        {
            @Override public boolean adaptiveDisplayTime() { return false; }
            @Override public int displayDuration() { return 4000; }
        };
        LootNotification n = new LootNotification("Boss", Collections.singletonList(
            new LootDisplayItem(1, 1, 100, "1 / 5000", 5000)), 100, 0);
        SealedDropSequence s = new SealedDropSequence(n.getItems(), Collections.emptySet(), 1000, true, false, 100, 10);
        n.setSealedDrop(s);
        assertEquals(4000 + s.getDurationMillis(), plugin(config).displayDurationFor(n));
        assertFalse(n.isExpired(s.getDurationMillis() + 3900, plugin(config).displayDurationFor(n), 500));
    }

    @Test
    public void performanceAndDisabledRevealDoNotPrepareASequence() throws Exception
    {
        for (LootPopConfig config : Arrays.asList(new LootPopConfig()
        {
            @Override public VisualMode visualMode() { return VisualMode.PERFORMANCE; }
        }, new LootPopConfig() { @Override public boolean sealedDrops() { return false; } }))
        {
            LootPopPlugin p = plugin(config);
            LootNotification n = new LootNotification("Boss", Collections.singletonList(
                new LootDisplayItem(1, 1, 100, "1 / 5000", 5000)), 100, 0);
            java.lang.reflect.Method prepare = LootPopPlugin.class.getDeclaredMethod("prepareSealedDrop", LootNotification.class);
            prepare.setAccessible(true);
            prepare.invoke(p, n);
            assertNull(n.getSealedDrop());
            assertEquals(0, n.getRevealDelayMillis());
        }
    }

    @Test
    @SuppressWarnings("unchecked")
    public void queueRestartsRevealClockRatherThanExpiringWhileWaiting() throws Exception
    {
        LootPopConfig config = new LootPopConfig()
        {
            @Override public boolean rareDropSounds() { return false; }
        };
        LootPopPlugin p = plugin(config);
        Field queue = LootPopPlugin.class.getDeclaredField("queuedNotifications");
        queue.setAccessible(true);
        LootNotification n = new LootNotification("Queued boss", Collections.singletonList(
            new LootDisplayItem(1, 1, 100, "1 / 5000", 5000)), 100, 0);
        n.setSealedDrop(new SealedDropSequence(n.getItems(), Collections.emptySet(), 1000, true, false, 100, 10));
        ((Deque<LootNotification>) queue.get(p)).add(n);
        assertTrue(p.getVisibleNotifications().contains(n));
        assertTrue(n.getAgeMillis(System.currentTimeMillis()) < 1000);
        assertEquals(0f, n.getSealedDrop().normalAlpha(n.getAgeMillis(System.currentTimeMillis())), 0.001f);
    }
}

package com.lootpop;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;
import net.runelite.client.ui.FontManager;
import org.junit.Test;
import static org.junit.Assert.*;

/** Offscreen motion fixture: production reveal painter, illustrative item sprites. No client/network needed. */
public class SealedDropRendererTest
{
    @Test
    public void paintsFullTimelineAndExportsLocalMotionPreview() throws Exception
    {
        Path directory = Path.of("build", "sealed-drop-preview");
        Files.createDirectories(directory);
        LootDisplayItem first = new LootDisplayItem(1, 1, 100000, "1 / 5,000", 5000);
        LootDisplayItem second = new LootDisplayItem(2, 1, 30000, "1 / 2,000", 2000);
        SealedDropSequence sequence = new SealedDropSequence(Arrays.asList(first, second,
            new LootDisplayItem(3, 15, 1, "1 / 2", 2)), Collections.singleton(1), 1000, true, false, 100, 10);
        SealedDropRenderer renderer = new SealedDropRenderer();
        BufferedImage[] sprites = {sword(new Color(227, 198, 99)), sword(new Color(137, 203, 210)), coins()};
        ImageWriter writer = ImageIO.getImageWritersByFormatName("gif").next();
        try (ImageOutputStream output = ImageIO.createImageOutputStream(directory.resolve("sealed-drop.gif").toFile()))
        {
            writer.setOutput(output);
            writer.prepareWriteSequence(null);
            for (int frame = 0; frame < 104; frame++)
            {
                BufferedImage image = frame(renderer, sequence, sprites, frame * 50L);
                IIOMetadata meta = writer.getDefaultImageMetadata(javax.imageio.ImageTypeSpecifier.createFromRenderedImage(image), writer.getDefaultWriteParam());
                String format = meta.getNativeMetadataFormatName();
                IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree(format);
                IIOMetadataNode control = (IIOMetadataNode) root.getElementsByTagName("GraphicControlExtension").item(0);
                control.setAttribute("delayTime", "5");
                control.setAttribute("disposalMethod", "none");
                if (frame == 0)
                {
                    IIOMetadataNode extensions = new IIOMetadataNode("ApplicationExtensions");
                    IIOMetadataNode loop = new IIOMetadataNode("ApplicationExtension");
                    loop.setAttribute("applicationID", "NETSCAPE");
                    loop.setAttribute("authenticationCode", "2.0");
                    loop.setUserObject(new byte[]{1, 0, 0});
                    extensions.appendChild(loop);
                    root.appendChild(extensions);
                }
                meta.setFromTree(format, root);
                writer.writeToSequence(new IIOImage(image, null, meta), writer.getDefaultWriteParam());
            }
            writer.endWriteSequence();
        }
        finally { writer.dispose(); }
        BufferedImage sheet = new BufferedImage(660, 420, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = sheet.createGraphics();
        g.setColor(new Color(13, 15, 19));
        g.fillRect(0, 0, 660, 420);
        long[] times = {400, 1100, 2300, 4200};
        for (int i = 0; i < times.length; i++)
        {
            g.drawImage(frame(renderer, sequence, sprites, times[i]), 10 + (i % 2) * 330, 10 + (i / 2) * 210, null);
        }
        g.dispose();
        ImageIO.write(sheet, "png", directory.resolve("stages.png").toFile());
        assertTrue(Files.size(directory.resolve("sealed-drop.gif")) > 10000);
    }

    private static BufferedImage frame(SealedDropRenderer renderer, SealedDropSequence sequence,
        BufferedImage[] sprites, long age)
    {
        BufferedImage image = new BufferedImage(320, 200, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.setColor(new Color(17, 20, 26));
        g.fillRect(0, 0, 320, 200);
        g.setColor(new Color(35, 39, 47));
        g.fillRoundRect(3, 3, 313, 177, 8, 8);
        g.setColor(new Color(123, 135, 158));
        g.drawRoundRect(3, 3, 313, 177, 8, 8);
        g.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
        g.setColor(new Color(241, 223, 173));
        g.drawString("Rare drop test", 12, 24);
        g.setColor(new Color(210, 215, 223));
        g.drawString(age < sequence.getRevealEndMillis() ? "??? gp" : "130K gp", 246, 24);
        g.setColor(new Color(80, 88, 104));
        g.drawLine(12, 31, 306, 31);
        String[] names = {"Ancient blade", "Rune blade"};
        for (int i = 0; i < 3; i++)
        {
            boolean candidate = i < 2;
            if (candidate && sequence.progress(age, i) >= 1)
            {
                g.drawImage(sprites[i], 12 + i * 41, 38, null);
                if (i == 0) { SealedDropRenderer.drawBook(g, 35, 59, SealedDropRenderer.COLLECTION_GOLD); }
            }
            else if (!candidate)
            {
                Graphics2D normal = (Graphics2D) g.create();
                SealedDropRenderer.fade(normal, sequence.normalAlpha(age));
                normal.drawImage(sprites[i], 12 + i * 41, 38, null);
                normal.setFont(FontManager.getRunescapeSmallFont());
                normal.setColor(Color.WHITE);
                normal.drawString("x15", 94, 50);
                normal.dispose();
            }
            if (candidate)
            {
                renderer.draw(g, sequence.getItems().get(i), sprites[i], names[i], new Color(235, 73, 105),
                    i == 0, sequence.progress(age, i), 160, 105, 12 + i * 41, 38, 285, false, true);
            }
        }
        if (age < sequence.getRevealEndMillis())
        {
            g.setFont(FontManager.getRunescapeSmallFont().deriveFont(11f));
            g.setColor(new Color(176, 182, 197));
            String label = "SEALED DROP  " + (sequence.progress(age, 1) < 0 ? "1 / 2" : "2 / 2");
            g.drawString(label, (320 - g.getFontMetrics().stringWidth(label)) / 2, 78);
        }
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
        g.setColor(new Color(138, 145, 161));
        g.drawString("Motion preview / illustrative sprites", 65, 195);
        g.dispose();
        return image;
    }

    static BufferedImage sword(Color metal)
    {
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(4, 5, 8));
        g.fillPolygon(new int[]{5, 8, 14, 29, 33, 32, 17, 22, 19, 13, 8},
            new int[]{27, 22, 19, 2, 1, 7, 23, 25, 29, 25, 31}, 11);
        g.setColor(metal);
        g.fillPolygon(new int[]{13, 28, 31, 30, 15}, new int[]{19, 4, 3, 7, 22}, 5);
        g.setColor(new Color(245, 247, 236));
        g.drawLine(15, 19, 29, 5);
        g.setColor(new Color(227, 172, 53));
        g.fillRect(10, 18, 4, 5);
        g.fillRect(14, 22, 6, 3);
        g.setColor(new Color(133, 75, 37));
        g.fillRect(7, 24, 6, 4);
        g.dispose();
        return image;
    }

    static BufferedImage coins()
    {
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        for (int i = 0; i < 3; i++)
        {
            g.setColor(new Color(117, 76, 9));
            g.fillOval(3 + i * 9, 13 - i * 3, 13, 8);
            g.setColor(new Color(248, 192, 50));
            g.fillOval(4 + i * 9, 13 - i * 3, 11, 5);
        }
        g.dispose();
        return image;
    }
}

package com.lootpop;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class SealedDropSequenceTest
{
    private static LootDisplayItem item(int id, double rate)
    {
        return new LootDisplayItem(id, 1, 100, rate == 0 ? null : "1 / " + rate, rate);
    }

    private static SealedDropSequence sequence(List<LootDisplayItem> items)
    {
        return new SealedDropSequence(items, Collections.emptySet(), 1000, true, false, 100, 10);
    }

    @Test
    public void settlesFirstRareBeforeSecondAndOnlyThenFadesOrdinaryLoot()
    {
        LootDisplayItem common = item(1, 128);
        SealedDropSequence s = sequence(Arrays.asList(common, item(2, 5000), item(3, 2000)));
        assertEquals(2, s.getCandidateCount());
        assertEquals(2, s.getItems().get(0).getItemId());
        assertSame(common, s.getItems().get(2));
        assertTrue(s.progress(1800, 0) >= 1);
        assertTrue(s.progress(1800, 1) > 0 && s.progress(1800, 1) < 1);
        assertEquals(0f, s.normalAlpha(1800), 0.001f);
        assertEquals(0f, s.normalAlpha(s.getRevealEndMillis()), 0.001f);
        assertEquals(0.5f, s.normalAlpha(s.getRevealEndMillis() + 90), 0.001f);
        assertEquals(1f, s.normalAlpha(s.getDurationMillis()), 0.001f);
    }

    @Test
    public void manyRaresHaveOnlyThreeBoundedStagesAndRetainAllItems()
    {
        List<LootDisplayItem> items = new ArrayList<>();
        for (int i = 0; i < 20; i++) { items.add(item(i, 5000)); }
        SealedDropSequence s = sequence(items);
        assertEquals(3, s.getStageCount());
        assertEquals(10, s.getCandidateCount());
        assertEquals(20, s.getItems().size());
        assertEquals(2, s.getStage(9));
        assertTrue(s.getDurationMillis() < 6000);
    }

    @Test
    public void onlyConfirmedUnlocksTriggerCommonItemReveals()
    {
        List<LootDisplayItem> items = Arrays.asList(item(1, 0), item(2, 2));
        assertEquals(0, sequence(items).getCandidateCount());
        SealedDropSequence confirmed = new SealedDropSequence(items, Collections.singleton(2),
            1000, true, false, 100, 10);
        assertEquals(1, confirmed.getCandidateCount());
        assertEquals(2, confirmed.getItems().get(0).getItemId());
        assertEquals(0, new SealedDropSequence(items, Collections.singleton(2),
            1000, false, false, 100, 10).getCandidateCount());
    }

    @Test
    public void reducedMotionUsesOneBriefFadeAndUnknownRatesDoNotGuessRarity()
    {
        SealedDropSequence s = new SealedDropSequence(Arrays.asList(item(1, 0), item(2, 5000), item(3, 2000)),
            Collections.emptySet(), 1000, true, true, 100, 10);
        assertTrue(s.isReducedMotion());
        assertEquals(1, s.getStageCount());
        assertEquals(2, s.getCandidateCount());
        assertTrue(s.getDurationMillis() < 1000);
    }

    @Test
    public void visibleCapacityReservesOverflowBadge()
    {
        LootPopConfig config = new LootPopConfig() { @Override public int maxItems() { return 10; } };
        assertEquals(9, LootPopOverlay.visibleItemCount(config, 20));
        assertEquals(10, LootPopOverlay.visibleItemCount(config, 10));
    }

    @Test
    public void skipPreservesReadingTimeAndItemOrderWithoutReplaying()
    {
        LootNotification n = new LootNotification("Boss", Arrays.asList(item(1, 128), item(2, 5000)), 200, 1000);
        n.setSealedDrop(sequence(n.getItems()));
        n.skipReveal(1800);
        assertNull(n.getSealedDrop());
        assertEquals(800, n.getRevealDelayMillis());
        assertEquals(2, n.getDisplayItems().get(0).getItemId());
        assertFalse(n.isExpired(4800, (int) (3000 + n.getRevealDelayMillis()), 500));
        n.skipReveal(3000);
        assertEquals(800, n.getRevealDelayMillis());
    }

    @Test
    public void lateCollectionUnlockDoesNotReplaceTimelineAndDuplicatesAreIgnored()
    {
        LootNotification n = new LootNotification("Boss", Arrays.asList(item(1, 128), item(2, 5000)), 200, 1000);
        SealedDropSequence s = sequence(n.getItems());
        n.setSealedDrop(s);
        assertTrue(n.markCollectionLogItem(1, 5000));
        assertEquals(4000, n.getLateUnlockAtAge());
        assertSame(s, n.getSealedDrop());
        assertTrue(n.isCollectionLogItem(1));
        assertFalse(n.isCollectionLogItem(2));
        assertFalse(n.markCollectionLogItem(1, 5500));
        assertEquals(4000, n.getLateUnlockAtAge());
    }

    @Test
    public void revealSoundsAreTakenOnlyOncePerStage()
    {
        LootNotification n = new LootNotification("Boss", Collections.emptyList(), 0, 0);
        assertTrue(n.takeRevealSound(0));
        assertFalse(n.takeRevealSound(0));
        assertTrue(n.takeRevealSound(1));
        assertFalse(n.takeRevealSound(0));
        assertTrue(n.takeSound());
        assertFalse(n.takeSound());
    }

    @Test
    public void syntheticPreviewsNeverRequestAutomaticScreenshots()
    {
        LootNotification n = new LootNotification("Test", Collections.emptyList(), 0, 0);
        assertFalse(n.takeScreenshot());
        n.requestScreenshot();
        assertTrue(n.takeScreenshot());
        assertFalse(n.takeScreenshot());
    }

    @Test
    public void collectionMessagesRequireTheExactServerPrefixAndItemName()
    {
        assertEquals("twisted bow", LootPopPlugin.collectionLogItemName("New item added to your collection log: Twisted bow"));
        assertNull(LootPopPlugin.collectionLogItemName("Player says New item added to your collection log: Twisted bow"));
        assertNull(LootPopPlugin.collectionLogItemName("New item added to your collection log: "));
        assertNull(LootPopPlugin.collectionLogItemName(null));
    }

    @Test
    public void hoverCannotFreezeTheFinalFadeButPausesReadingAfterItCompletes()
    {
        LootNotification n = new LootNotification("Boss", Collections.singletonList(item(1, 5000)), 100, 1000);
        SealedDropSequence s = sequence(n.getItems()); n.setSealedDrop(s);
        long revealEnd = 1000 + s.getRevealEndMillis();
        n.setHovered(true, revealEnd + 20);
        assertEquals(s.getDurationMillis(), n.getAgeMillis(1000 + s.getDurationMillis()));
        assertEquals(1f, s.normalAlpha(n.getAgeMillis(1000 + s.getDurationMillis())), 0.001f);
        n.setHovered(true, 1000 + s.getDurationMillis());
        assertEquals(s.getDurationMillis(), n.getAgeMillis(20000));
    }

    @Test
    public void slowRevealSpeedDoesNotCreateALongEmptyTransitionBetweenStagesAndNormalLoot()
    {
        SealedDropSequence s = new SealedDropSequence(Collections.singletonList(item(1, 5000)),
            Collections.emptySet(), 1000, true, false, 50, 10);
        assertTrue(s.getDurationMillis() - s.getRevealEndMillis() <= 200);
        assertEquals(1f, s.normalAlpha(s.getRevealEndMillis() + 200), 0.001f);
    }
}

package com.lootpop;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import static org.junit.Assert.*;

public class TooltipPresentationTest
{
    static LootPopOverlay overlay(LootPopConfig config)
    {
        LootPopPlugin plugin = new LootPopPlugin()
        { @Override DropRarity rarityForRate(double rate) { return DropRarity.ULTRA_RARE; } };
        return new LootPopOverlay(plugin, config, null, null, new TooltipManager(),
            item -> SealedDropRendererTest.coins(), item -> "Reward " + item.getItemId());
    }

    @Test public void oneItemHasNeitherQuantityNorStackButHasColouredUnitPrices()
    {
        LootPopOverlay overlay = overlay(new LootPopConfig() {});
        String text = overlay.buildItemTooltip(new LootDisplayItem(1, 1, 50, "1 / 5000", 5000), "Relic", 50, 70, false);
        assertFalse(text.contains("Qty:")); assertFalse(text.contains("Stack:"));
        assertTrue(text.contains(ColorUtil.wrapWithColorTag("50 gp", LootTooltipStyle.rarity(DropRarity.ULTRA_RARE, RarityPalette.DEFAULT))));
        assertTrue(text.contains(ColorUtil.wrapWithColorTag("70 gp", LootTooltipStyle.ALCH_PROFIT)));
    }

    @Test public void quantityAndStackAppearForDuplicatesAndHaComparesUnitNotStack()
    {
        String text = overlay(new LootPopConfig() {}).buildItemTooltip(
            new LootDisplayItem(1, 100, 50), "Relic", 50, 70, false);
        assertTrue(text.contains("Qty:")); assertTrue(text.contains("Stack:")); assertTrue(text.contains("5,000 gp"));
        assertTrue(text.contains(ColorUtil.wrapWithColorTag("70 gp", LootTooltipStyle.ALCH_PROFIT)));
        assertEquals(Color.WHITE, LootTooltipStyle.highAlchemy(50, 50, false));
        assertEquals(Color.WHITE, LootTooltipStyle.highAlchemy(50, 10, false));
        assertEquals(Color.WHITE, LootTooltipStyle.highAlchemy(0, 70, true));
    }

    @Test public void pendingPriceDoesNotPretendToBeAnAlchProfit()
    {
        String text = overlay(new LootPopConfig() {}).buildItemTooltip(
            new LootDisplayItem(1, 2, 0, null, 0, true), "New item", 0, 70, true);
        assertTrue(text.contains("Price pending"));
        assertTrue(text.contains(ColorUtil.wrapWithColorTag("70 gp", Color.WHITE)));
        assertFalse(text.contains(ColorUtil.wrapWithColorTag("70 gp", LootTooltipStyle.ALCH_PROFIT)));
    }

    @Test public void compactCustomModesAndColourblindPaletteRemainSupported()
    {
        LootDisplayItem item = new LootDisplayItem(1, 2, 50);
        String compact = overlay(new LootPopConfig() {
            @Override public HoverDetailMode hoverDetailMode() { return HoverDetailMode.COMPACT; }
        }).buildItemTooltip(item, "Relic", 50, 70, false);
        assertFalse(compact.contains("GE:")); assertTrue(compact.contains("Stack:"));
        String custom = overlay(new LootPopConfig() {
            @Override public HoverDetailMode hoverDetailMode() { return HoverDetailMode.CUSTOM; }
            @Override public boolean hoverShowStackValue() { return false; }
            @Override public boolean hoverShowDropChance() { return false; }
            @Override public boolean hoverShowPrices() { return true; }
            @Override public RarityPalette rarityPalette() { return RarityPalette.COLOURBLIND; }
        }).buildItemTooltip(item, "Relic", 50, 70, false);
        assertFalse(custom.contains("Stack:")); assertFalse(custom.contains("Chance:"));
        assertTrue(custom.contains(ColorUtil.wrapWithColorTag("50 gp", LootTooltipStyle.rarity(DropRarity.ULTRA_RARE, RarityPalette.COLOURBLIND))));
    }

    @Test public void sidePanelUsesTheSameRulesAndEscapesNames()
    {
        LootHistoryItem single = history(1, 50, 70);
        String one = LootPopPanel.itemTooltip(single, RarityPalette.DEFAULT);
        assertFalse(one.contains("Qty:")); assertFalse(one.contains("Stack:"));
        assertTrue(one.contains("&lt;Relic&gt; &amp; stone"));
        assertTrue(one.contains("<font color='#69d17d'>70 gp</font>"));
        String stack = LootPopPanel.itemTooltip(history(2, 50, 50), RarityPalette.DEFAULT);
        assertTrue(stack.contains("Qty:")); assertTrue(stack.contains("Stack:"));
        assertTrue(stack.contains("<font color='#ffffff'>50 gp</font>"));
    }

    @Test public void groupedPricesUseMatchedObservationsNotUnrelatedRangeEndpoints()
    {
        LootHistoryEntry first = entry(history(1, 100, 150));
        LootHistoryEntry second = entry(history(1, 200, 250));
        LootDaySummary.Item combined = LootDaySummary.items(Arrays.asList(first, second)).get(0);
        assertTrue(combined.allHaAboveGe);
        String text = LootPopPanel.dailyTooltip(combined, RarityPalette.DEFAULT);
        assertTrue(text.contains("Qty:")); assertTrue(text.contains("Stack:"));
        assertTrue(text.contains("color='#69d17d'>150 gp"));
        LootDaySummary.Item mixed = LootDaySummary.items(Arrays.asList(first, entry(history(1, 200, 190)))).get(0);
        assertFalse(mixed.allHaAboveGe);
        assertTrue(LootPopPanel.dailyTooltip(mixed, RarityPalette.DEFAULT).contains("color='#ffffff'>150 gp"));
        String one = LootPopPanel.dailyTooltip(LootDaySummary.items(Collections.singletonList(first)).get(0), RarityPalette.DEFAULT);
        assertFalse(one.contains("Qty:")); assertFalse(one.contains("Stack:"));
    }

    @Test public void hiddenRowsKeepUnknownPricesExplicitAndLimitThePreviewList()
    {
        java.util.List<LootDisplayItem> items = new java.util.ArrayList<>();
        items.add(new LootDisplayItem(1, 1, 0, null, 0, true));
        for (int id = 2; id <= 12; id++) { items.add(new LootDisplayItem(id, id, 50)); }
        HiddenItemsTooltip tooltip = overlay(new LootPopConfig() {}).buildHiddenItemsTooltip(items, 0);
        assertEquals(10, tooltip.getChildren().size()); // title + 8 rows + more
        HiddenItemsTooltip.ItemRow first = (HiddenItemsTooltip.ItemRow) tooltip.getChildren().get(1);
        assertEquals("Price pending", first.getValue()); assertEquals("Reward 1", first.getName());
        assertEquals("Reward 2 x2", ((HiddenItemsTooltip.ItemRow) tooltip.getChildren().get(2)).getName());
    }

    private static LootHistoryItem history(int qty, long ge, long ha)
    { return new LootHistoryItem(qty, "<Relic> & stone", ge, ha, ge * qty, "1 / 5000", DropRarity.ULTRA_RARE, null).withItemId(1); }
    private static LootHistoryEntry entry(LootHistoryItem item)
    { return new LootHistoryEntry("Boss", item.getStackValue(), 1, DropRarity.ULTRA_RARE, Collections.singletonList(item)); }
}

package com.lootpop;

import java.nio.file.Files;
import java.util.Collections;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import static com.lootpop.JournalTestFiles.*;

public class TrophyShelfTest
{
    @Rule public TemporaryFolder temporary = new TemporaryFolder();

    private static LootHistoryEntry drop(String source, long value, long time, DropRarity rarity)
    {
        return new LootHistoryEntry(source, value, time, rarity, Collections.singletonList(
            new LootHistoryItem(1, "Relic", value, 100, value, null, rarity, null).withItemId(1)));
    }

    @Test
    public void trophyRetentionIsIndependentFromHistoryAgeAndCount()
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        LootHistoryEntry old = drop("Boss", 1000, now - 100 * 86400000L, DropRarity.ULTRA_RARE);
        journal.record(old, 1, 1, now, 50);
        assertTrue(journal.snapshot().isEmpty()); assertEquals(1, journal.trophySnapshot().size());
        journal.record(drop("Boss", 1, now, DropRarity.COMMON), 1, 1, now, 50);
        journal.record(drop("Boss", 2, now + 1, DropRarity.COMMON), 1, 1, now, 50);
        assertEquals(1, journal.snapshot().size()); assertSame(old, journal.trophySnapshot().get(0));
    }

    @Test
    public void oneDropWithThreeReasonsOccupiesOnlyOneShelfPlace()
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        LootHistoryEntry entry = drop("Boss", 1000, now, DropRarity.ULTRA_RARE);
        entry.setCollectionLogUnlock(true); journal.record(entry, 100, 90, now, 50);
        journal.keepTrophy(entry, 50); journal.record(entry, 100, 90, now, 50);
        assertEquals(1, journal.snapshot().size()); assertEquals(1, journal.trophySnapshot().size());
        assertTrue(entry.isSourceBest()); assertTrue(entry.isCollectionLogUnlock());
    }

    @Test
    public void sourceChampionsReplaceOnlyBestOnlyEntriesAndValuationModesAreIndependent()
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        LootHistoryEntry first = drop("Boss", 100, now, DropRarity.COMMON);
        LootHistoryEntry second = drop("Boss", 200, now + 1, DropRarity.COMMON);
        journal.record(first, 100, 90, now); journal.record(second, 100, 90, now);
        assertFalse(first.isSourceBest()); assertEquals(1, journal.trophySnapshot().size());
        LootHistoryEntry alch = drop("Boss", 50, now + 2, DropRarity.COMMON);
        alch.setPriceMode(PriceMode.HIGH_ALCHEMY); journal.record(alch, 100, 90, now);
        assertEquals(2, journal.trophySnapshot().size());
        second.setCollectionLogUnlock(true);
        journal.record(drop("Boss", 300, now + 3, DropRarity.COMMON), 100, 90, now);
        assertEquals(3, journal.trophySnapshot().size()); assertFalse(second.isSourceBest());
    }

    @Test
    public void shelfUsesExplicitSeparateCapacityAndKeepsNewestTrophies()
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        for (int i = 0; i < 5; i++) { journal.record(drop("Boss", i + 1, now + i, DropRarity.ULTRA_RARE), 100, 90, now, 2); }
        assertEquals(5, journal.snapshot().size()); assertEquals(2, journal.trophySnapshot().size());
        assertEquals(now + 4, journal.trophySnapshot().get(0).getTimestamp());
    }

    @Test
    public void shelfOnlyEntriesAndPendingFlagsSurviveSaveAndReload() throws Exception
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        LootHistoryItem relic = new LootHistoryItem(1, "New relic", 0, 12000, 0, "1 / 5000", DropRarity.ULTRA_RARE, null)
            .withItemId(1).withPriceState(true, true);
        relic.setCollectionLogItem(true);
        LootHistoryEntry entry = new LootHistoryEntry("Boss", 0, now - 100 * 86400000L,
            DropRarity.ULTRA_RARE, Collections.singletonList(relic));
        entry.setCollectionLogUnlock(true); journal.record(entry, 100, 1, now);
        LootJournalStore store = store(temporary.newFolder().toPath(), new com.google.gson.Gson()); store.save("A", journal);
        LootJournal loaded = store.load("A"); assertTrue(loaded.snapshot().isEmpty());
        LootHistoryEntry trophy = loaded.trophySnapshot().get(0);
        assertEquals(entry.getId(), trophy.getId()); assertTrue(trophy.hasPendingPrices());
        assertTrue(trophy.getItems().get(0).isGePending()); assertTrue(trophy.getItems().get(0).isCollectionLogItem());
        assertFalse(trophy.isSourceBest()); assertTrue(loaded.bests.isEmpty());
    }

    @Test
    public void historyAndShelfShareOneCanonicalEntryAfterReload() throws Exception
    {
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        journal.record(drop("Boss", 1000, now, DropRarity.ULTRA_RARE), 100, 90, now);
        LootJournalStore store = store(temporary.newFolder().toPath(), new com.google.gson.Gson()); store.save("A", journal);
        LootJournal loaded = store.load("A"); assertSame(loaded.snapshot().get(0), loaded.trophySnapshot().get(0));
    }

    @Test
    public void legacyJournalIsReadWithoutLosingHistoryAndCreatesShelfFromAvailableMetadata() throws Exception
    {
        LootJournalStore store = store(temporary.newFolder().toPath(), new com.google.gson.Gson());
        LootJournal journal = new LootJournal(); long now = System.currentTimeMillis();
        journal.record(drop("Boss", 1000, now, DropRarity.ULTRA_RARE), 100, 90, now);
        store.save("A", journal);
        com.google.gson.JsonObject legacy = new com.google.gson.JsonParser().parse(Files.readString(pathFor(store, "A"))).getAsJsonObject();
        legacy.addProperty("version", 1); legacy.remove("history"); legacy.remove("trophies");
        for (com.google.gson.JsonElement element : legacy.getAsJsonArray("entries"))
        { element.getAsJsonObject().remove("id"); element.getAsJsonObject().remove("sourceBest"); }
        Files.writeString(pathFor(store, "A"), legacy.toString());
        LootJournal loaded = store.load("A"); assertEquals(1, loaded.snapshot().size());
        assertEquals(1, loaded.trophySnapshot().size()); assertTrue(loaded.trophySnapshot().get(0).isSourceBest());
        assertTrue(Files.readString(pathFor(store, "A")).contains("\"version\":1"));
        store.save("A", loaded);
        assertTrue(Files.readString(pathFor(store, "A")).contains("\"version\":2"));
        assertTrue(Files.readString(pathFor(store, "A").resolveSibling(pathFor(store, "A").getFileName() + ".bak")).contains("\"version\":1"));
    }
}

package com.lootpop;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WildcardMatcherTest
{
    @Test
    public void matchesCaseInsensitiveWildcards()
    {
        assertTrue(WildcardMatcher.matchesAny("bones, dragon *", "Dragon dagger"));
        assertTrue(WildcardMatcher.matchesAny("*goblin", "Cave goblin"));
        assertFalse(WildcardMatcher.matchesAny("bones, dragon *", "Coins"));
    }

    @Test
    public void handlesEmptyPatterns()
    {
        assertFalse(WildcardMatcher.matchesAny("", "Coins"));
        assertFalse(WildcardMatcher.matchesAny(null, "Coins"));
    }
}
